Q: XmlSerializer Read KeyValueOfstring A: <p>The inner elements have no prefix, so they're in the default namespace, while the wrapper elements are prefixed. Getting that split right is what you have to do:</p>
<pre><code>[XmlRoot(&quot;MyXML&quot;)]
public class MyXml
{
    [XmlArray(&quot;MySection1&quot;)]
    [XmlArrayItem(&quot;KeyValueOfstringMySection&quot;,
        Namespace = &quot;http://schemas.microsoft.com/2003/10/Serialization/Arrays&quot;)]
    public List&lt;KeyValuePairItem&gt; Section1 { get; set; }
}

public class KeyValuePairItem
{
    [XmlElement(&quot;Key&quot;, Namespace = &quot;http://schemas.microsoft.com/2003/10/Serialization/Arrays&quot;)]
    public string Key { get; set; }

    [XmlElement(&quot;Value&quot;, Namespace = &quot;http://schemas.microsoft.com/2003/10/Serialization/Arrays&quot;)]
    public MySection Value { get; set; }
}

public class MySection
{
    [XmlElement(&quot;MaxValue&quot;, IsNullable = true)]
    public string MaxValue { get; set; }

    [XmlElement(&quot;MinValue&quot;, IsNullable = true)]
    public string MinValue { get; set; }

    public string Name { get; set; }
    public string Value { get; set; }
}
</code></pre>
<p>If you only need to change a value, <code>XDocument</code> is far less work, no class hierarchy, no namespace mapping, and it won't break when the <code>d4p1</code> prefix changes, which it does between serializations.</p>
<pre><code>var doc = XDocument.Load(xmlPath);
var node = doc.Descendants(&quot;Name&quot;).First(e =&gt; e.Value == &quot;MyKey&quot;).Parent;
node.Element(&quot;Value&quot;).Value = &quot;NewValue&quot;;
doc.Save(xmlPath);
</code></pre>
